using System; using System.Collections.Generic; using System.Linq; using SuijinMaterials.Content;
namespace SuijinMaterials.Merchants { public static class MerchantStockCatalogValidator { public static IReadOnlyList<string> Validate(IEnumerable<MerchantStockDefinition> definitions){var errors=new List<string>();var all=(definitions??Array.Empty<MerchantStockDefinition>()).ToArray();foreach(var g in all.GroupBy(x=>x.ListingId).Where(x=>x.Count()>1))errors.Add("Duplicate merchant listing ID '"+g.Key+"'.");var known=new HashSet<string>(MaterialCatalog.All.Select(x=>x.PrefabId));foreach(var x in all){if(string.IsNullOrWhiteSpace(x.TraderPrefabId))errors.Add(x.ListingId+" missing trader.");if(!known.Contains(x.MaterialPrefabId))errors.Add(x.ListingId+" unknown material.");if(x.Price<1||x.Stack<1)errors.Add(x.ListingId+" invalid price or stack.");}return errors.AsReadOnly();} } }
